-- Lexicographic Batch 03: source-conservative editorial changes to foundational term families.
-- Copy and conceptual separation only. No formula, interpretation, citation, alias or reference scheme is edited.
-- All source-dependent claims are inherited from the already-reviewed author accounts; this is not a fresh primary-source extraction.
PRAGMA foreign_keys=ON;

UPDATE term_article_sections SET heading='Signification and celestial causation',body='Abū Maʿshar discusses celestial power and celestial indication as related but distinct ideas. Power concerns changes attributed to the heavenly bodies in the sublunary world; indication concerns the relation by which a celestial state signifies something else. An astrologer''s statement that a configuration indicates an event does not, by that statement alone, specify the mechanism by which the event occurs.',editorial_notes='Lexicographic Batch 03: reviewed expression; source-specific differences and reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='indication') AND section_key='not-identical-cause';
UPDATE term_article_sections SET heading='The limits of practicable knowledge',body='A hidden indication is not a general licence to infer another person''s concealed thoughts. Abū Maʿshar''s distinction concerns the reliability with which celestial signs can be interpreted. Its subject is the limit of knowledge, not a separate technique for revealing secrets; attempts to judge unspoken questions belong to a different historical discussion.',editorial_notes='Lexicographic Batch 03: reviewed expression; source-specific differences and reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='hidden-indication') AND section_key='not-secret-reading';
UPDATE term_article_sections SET heading='Relative fixity and planetary motion',body='The word fixed describes the stars'' relative arrangement, not absolute immobility. In traditional astronomy the stellar sphere moves very slowly compared with the changing positions of the seven wandering planets. The contrast concerns apparent celestial motion rather than the stars'' physical nature.',editorial_notes='Lexicographic Batch 03: reviewed expression; source-specific differences and reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='fixed-stars') AND section_key='wandering-contrast';
UPDATE term_article_sections SET heading='Constellation and zodiacal sign distinguished',body='A constellation is a conventional stellar figure of irregular extent, whereas a zodiacal sign is a thirty-degree division of the zodiacal circle. Their traditional names sometimes coincide without making the two kinds of division identical. This distinction matters when a source describes a star as belonging to a constellation rather than occupying a sign.',editorial_notes='Lexicographic Batch 03: reviewed expression; source-specific differences and reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='constellation') AND section_key='not-zodiac-sign';
UPDATE term_article_sections SET heading='The two principal lights',body='Luminaries designates the Sun and Moon together, especially in doctrines that compare them with the five other traditional planets. It is a collective classification, not an independent celestial body or an additional calculated point.',editorial_notes='Lexicographic Batch 03: reviewed expression; source-specific differences and reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='luminaries') AND section_key='paired-lights';
UPDATE term_article_sections SET heading='The twenty-eight lunar stations',body='The lunar mansions arrange the Moon''s circuit into twenty-eight stations. Unlike zodiacal signs, they form a lunar positional framework used in particular electional, weather and related traditions. The names, boundaries and practical rules vary in transmitted systems and must be identified by source.',editorial_notes='Lexicographic Batch 03: reviewed expression; source-specific differences and reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='lunar-mansions') AND section_key='twenty-eight';
UPDATE term_article_sections SET heading='Increasing illumination in the lunation',body='The Moon waxes as its visible illuminated portion increases from conjunction toward opposition with the Sun. This describes synodic illumination, not a change in the rate of zodiacal motion, lunar latitude or any other quantity that can also rise or fall.',editorial_notes='Lexicographic Batch 03: reviewed expression; source-specific differences and reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='waxing') AND section_key='light-cycle';
UPDATE term_article_sections SET heading='Decreasing illumination in the lunation',body='The Moon wanes as its visible illuminated portion decreases after opposition, approaching the next conjunction with the Sun. The term concerns synodic illumination and does not by itself imply that the Moon is moving more slowly through the zodiac.',editorial_notes='Lexicographic Batch 03: reviewed expression; source-specific differences and reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='waning') AND section_key='light-cycle';
UPDATE term_article_sections SET heading='A nodal coordinate transformation',body='The draconic system assigns zero Aries to the Moon''s ascending node and shifts the remaining longitudes by the same amount. The angular separation between positions is preserved; their sign and degree labels change. This is a derived coordinate convention, not a newly observed belt of stars.',editorial_notes='Lexicographic Batch 03: reviewed expression; source-specific differences and reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='draconic-zodiac') AND section_key='derived-frame';
UPDATE term_article_sections SET heading='Nature distinguished from property',body='Abū Maʿshar distinguishes a planet''s elementary qualitative nature—its combinations of heat, cold, moisture and dryness—from a characteristic operative property or power. The two belong to his account of planetary action but are not interchangeable classifications.',editorial_notes='Lexicographic Batch 03: reviewed expression; source-specific differences and reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='planetary-nature') AND section_key='not-property';
UPDATE term_article_sections SET heading='An explanatory level beyond the four qualities',body='Planetary property names a characteristic mode of action not exhausted by the planet''s mixture of elemental qualities. In Abū Maʿshar''s account, nature and property can both contribute to an explanation of action without collapsing into a single list of hot, cold, wet and dry attributes.',editorial_notes='Lexicographic Batch 03: reviewed expression; source-specific differences and reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='planetary-property') AND section_key='nature-distinction';
UPDATE term_article_sections SET heading='Association and conditioned expression',body='A mixed planet''s manifestation depends on its company and circumstances. Mercury is the principal example in Abū Maʿshar''s classification: its expression may be more favorable or difficult in different configurations. Mixed therefore describes conditional behavior rather than an absence of planetary qualities.',editorial_notes='Lexicographic Batch 03: reviewed expression; source-specific differences and reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='mixed-planet') AND section_key='association';
UPDATE term_article_sections SET heading='Planetary and zodiacal gender are separate',body='Planetary masculinity is attributed to the planet; masculine and feminine signs form a different classification. A masculine planet may occupy a feminine sign, and some compound conditions evaluate the agreement or contrast between the two. The classifications should be compared, not merged.',editorial_notes='Lexicographic Batch 03: reviewed expression; source-specific differences and reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='planetary-masculinity') AND section_key='separate-classification';
UPDATE term_article_sections SET heading='The planet and its sign need not share gender',body='Planetary femininity concerns a planet''s attributed nature and may be compared with the masculine or feminine designation of its sign. The classifications are distinct: an author''s reference to the gender of the planet does not automatically describe the sign it occupies.',editorial_notes='Lexicographic Batch 03: reviewed expression; source-specific differences and reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='planetary-femininity') AND section_key='separate-classification';
UPDATE term_article_sections SET heading='The solar side of the domicile arrangement',body='The solar half extends from Leo through Capricorn. It begins from the Sun''s domicile, Leo, and belongs to a mirrored system that distributes the other planets'' domiciles outward from the two luminary domiciles, Leo and Cancer. It is not a second zodiacal circle.',editorial_notes='Lexicographic Batch 03: reviewed expression; source-specific differences and reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='solar-half') AND section_key='domicile-symmetry';
UPDATE term_article_sections SET heading='The lunar side of the domicile arrangement',body='The lunar half extends from Aquarius through Cancer and terminates at Cancer, the Moon''s domicile. Together with the solar half it describes the paired arrangement of planetary domiciles around the two lights, not an alternative partition into unequal signs.',editorial_notes='Lexicographic Batch 03: reviewed expression; source-specific differences and reference data preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='lunar-half') AND section_key='domicile-symmetry';
UPDATE term_articles SET intro='Medical astrology is the historical use of astrological categories in discussions of bodily condition, temperament, illness and medical timing. Premodern practitioners related such judgments to their medical theories; the terms describe a historical doctrine and do not supply contemporary clinical guidance.',editorial_notes='Lexicographic Batch 03: historically situated clinical-language correction.' WHERE term_id=(SELECT id FROM terms WHERE slug='medical-astrology');
